class Solution {
public:
    int maximumSum(vector<int>& nums) {
        const long long MOD = 1e9 + 7;
        unordered_map<long long, long long> f, c;
        long long ans = 0;
        for (long long x : nums) {
            long long d = (f[x - 1] + f[x + 1] + x % MOD * ((c[x - 1] + c[x + 1]) % MOD) + x) % MOD;
            ans = (ans + d) % MOD;
            f[x] = (f[x] + d) % MOD;
            c[x] = (c[x] + c[x - 1] + c[x + 1] + 1) % MOD;
        }
        return (int)ans;
    }
};

