class Solution {
    public int maximumSum(int[] nums) {
        final long MOD = 1_000_000_007L;
        Map<Long, Long> f = new HashMap<>(), c = new HashMap<>();
        long ans = 0;
        for (long x : nums) {
            long fm = f.getOrDefault(x - 1, 0L) + f.getOrDefault(x + 1, 0L);
            long cm = c.getOrDefault(x - 1, 0L) + c.getOrDefault(x + 1, 0L);
            long d = (fm + x % MOD * (cm % MOD) + x) % MOD;
            ans = (ans + d) % MOD;
            f.merge(x, d, Long::sum);
            c.merge(x, (cm + 1) % MOD, Long::sum);
        }
        return (int) ans;
    }
}

