var maximumSum = function(nums) {
    const MOD = 1e9 + 7;
    const f = new Map(), c = new Map();
    let ans = 0;
    for (const x of nums) {
        const fm = ((f.get(x - 1) || 0) + (f.get(x + 1) || 0)) % MOD;
        const cm = ((c.get(x - 1) || 0) + (c.get(x + 1) || 0)) % MOD;
        const d = (fm + x % MOD * cm % MOD + x) % MOD;
        ans = (ans + d) % MOD;
        f.set(x, ((f.get(x) || 0) + d) % MOD);
        c.set(x, ((c.get(x) || 0) + cm + 1) % MOD);
    }
    return ans;
};
